style.css:
@-moz-document domain("tiktok.com") {
/* palette */
:root {
  --my-bg: #100809 !important;
  --my-panel: #1a1014 !important;
  --my-red: #b33b50 !important;
  --my-wine: #702638 !important;
  --my-text: #eadcde !important;
  --my-muted: #a58c94 !important;
  --my-border: #49232e !important;
}

/* main background */
html, body, #app {
  background-color: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* wallpaper */
body {
  background-image:
    linear-gradient(
      rgba(10, 3, 6, 0.82),
      rgba(10, 3, 6, 0.88)
    ),
    url("https://i.ibb.co/REPLACE-IMAGE-LINK/image.jpg") !important;
  background-size: cover !important;
  background-position: center !important;
  background-attachment: fixed !important;
  background-repeat: no-repeat !important;
}

/* panels */
section, aside, nav, article,
[role="navigation"], [role="dialog"] {
  background-color: var(--my-panel) !important;
  color: var(--my-text) !important;
  border-color: var(--my-border) !important;
}

/* headings */
h1, h2, h3, h4 {
  color: var(--my-red) !important;
  font-family: Georgia, serif !important;
}

/* links */
a {
  color: #c46b7c !important;
}

a:hover {
  color: #f0b3bf !important;
}

/* buttons */
button {
  background: #24141a !important;
  color: #d9a0ac !important;
  border-color: var(--my-border) !important;
  border-radius: 10px !important;
}

button:hover {
  background: #3b1b26 !important;
  box-shadow: 0 0 12px #a8324830 !important;
}

/* input fields */
input, textarea, select {
  background: #1c1217 !important;
  color: var(--my-text) !important;
  border-color: #552b38 !important;
  border-radius: 10px !important;
}

/* selection */
::selection {
  background: #702638 !important;
  color: #fff !important;
}

/* scrollbar */
* {
  scrollbar-color: #702638 #100b0d !important;
}
}
